{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Encainide, a methoxybenzamide with a basic piperidine, had an absolute oral bioavailability of 32 ± 7% in normal subjects, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Letermovir, a lipophilic oral antiviral with an N-arylpiperazine and methoxyarene, had an estimated absolute oral bioavailability of 93.8% in healthy participants.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Daridorexant, which contains a methoxyphenyl and pyrrolidine amide, had an absolute oral bioavailability of 62% in healthy subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Alizapride, a pyrrolidine-containing methoxyaryl amide, had an absolute oral availability of 72.5% after oral dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Brexpiprazole, a lipophilic basic amine drug, showed a mean absolute oral bioavailability of 95% in healthy subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Vernakalant, a dimethoxyphenyl pyrrolidine ether, had an absolute oral bioavailability of 71 ± 21% in fasted healthy volunteers, closely matching the query's methoxyaryl/pyrrolidine motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "The active metabolite of nabumetone, a methoxyaryl ketone, had a mean absolute oral bioavailability of 38% in healthy subjects, supporting adequate oral exposure for this ketone-containing scaffold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "High: the query's basic trimethoxybenzoyl-pyrrolidine structure aligns with multiple high-transfer analogues whose measured absolute oral bioavailability ranges from about 32% to 95% in humans, all above the 20% threshold. No affirmative threshold-relevant evidence indicates F < 20%.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement exists for the exact query molecule.",
    "Encainide data show wide interindividual variability (7–82%) and disease-dependent F, so first-pass metabolism could lower F in some populations, though mean values remain above 20%.",
    "Letermovir F was about 35% in HCT patients versus ~94% in healthy subjects, indicating patient status can reduce F, but still above the threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

